section(__T["Escape"], function()
    local Tab = Window:AddTab(__T["Escape"], "footprints")
    local B = Tab:AddLeftGroupbox(__T["Auto Escape"], "flag")
    B:AddToggle("e_auto", { Text = __T["Auto Escape"], Default = false, Tooltip = __T["Clears every room for you"], Callback = function(v) if v then task.spawn(startBot) else stopBot() M.status = __T["Stopped"] end end })
    B:AddToggle("e_speed", { Text = __T["Speed Mode"], Default = false, Tooltip = __T["Shorter routes, faster runs"], Callback = function(v) _G.__SPEED = v end })
    B:AddToggle("e_retry", { Text = __T["Retry Failed Room"], Default = true, Tooltip = __T["Tries again from where you stand"] })
    local st = B:AddLabel(__T["Idle"], true)
    local AB = Tab:AddRightGroupbox(__T["After Escape"], "repeat")
    AB:AddToggle("e_again", { Text = __T["Auto Play Again"], Default = false, Tooltip = __T["Skips the results wait"] })
    AB:AddToggle("e_lobby", { Text = __T["Auto Return to Lobby"], Default = false })
    local sx = AB:AddLabel("", true)
    task.spawn(function()
        local sent = 0
        while RUNNING do
            local idx, room = M.roomIndex()
            local sup = _G.__SUP
            local line
            if botRunning() then
                local run = _G.__RUN and _G.__RUN.lines
                local last = run and run[#run] or ""
                line = __T["Room "] .. idx .. " · " .. M.niceRoom(room)
                if last:find("STOP") or last:find("not clean") then line = line .. __T["\nRetrying room"] end
            elseif on("e_auto") then
                if sup and sup.done then
                    local l = sup.lines[#sup.lines] or ""
                    line = l:find("ESCAPED") and __T["Escaped!"] or (l:find("giving up") and __T["Stopped: room failed 4x"] or __T["Waiting"])
                else
                    line = __T["Starting..."]
                end
            else
                line = __T["Idle · Room "] .. idx .. " · " .. M.niceRoom(room)
            end
            setText(st, line)
            local esc = (lp:GetAttribute("Escapes") or 0) - M.esc0
            local rs = M.results
            local lines = { __T["Escapes this session  <b>"] .. esc .. "</b>" }
            if rs and rs.seconds then lines[#lines + 1] = __T["Last run  <b>"] .. clock(rs.seconds) .. "</b>" end
            if rs and rs.total then lines[#lines + 1] = __T["Last coins  <b>"] .. fmt(rs.total) .. "</b>" end
            setText(sx, table.concat(lines, "\n"))
            if rs and M.resultsAt and os.clock() - M.resultsAt < 60 and os.clock() - sent > 8 then
                if on("e_again") and M.PlayAgain then sent = os.clock() M.PlayAgain:FireServer()
                elseif on("e_lobby") and M.ToLobby then sent = os.clock() M.ToLobby:FireServer() end
            end
            if on("e_auto") and not botRunning() and not lp:GetAttribute("RunEnd") and lp.Character ~= M.supChar then
                local h = hum()
                if h and h.Health > 0 then task.spawn(startBot) end
            end
            local ok, em = pcall(function() return game:GetService("GuiService"):GetErrorMessage() end)
            if ok and em and em ~= "" then _G.__SW_KICKED = true end
            task.wait(1)
        end
    end)
end)
