    task.spawn(function()
        local lastAt, lastSlab, lastRoom, wasOn = 0, nil, nil, false
        local function step()
            local active = on("p_on") and not botRunning()
            if active then
                local r = hrp()
                local idx, room = M.roomIndex()
                local slab
                if r and room then
                    local rp = RaycastParams.new() rp.FilterType = Enum.RaycastFilterType.Include rp.FilterDescendantsInstances = { room }
                    local hit = Workspace:Raycast(r.Position, Vector3.new(0, -8, 0), rp)
                    slab = hit and hit.Instance
                end
                local offRoute = false
                if r and _G.__PLAN and _G.__PLAN.room == (room and room.Name) then
                    local best = math.huge
                    for _, e in ipairs(_G.__PLAN.steps) do
                        for _, q in ipairs({ e[3], e[4] }) do local d = (Vector3.new(q.X, 0, q.Z) - Vector3.new(r.Position.X, 0, r.Position.Z)).Magnitude if d < best then best = d end end
                    end
                    offRoute = best > 30
                end
                local movers = room and room.Name:find("MovingPlatforms")
                local flashNew = room and room.Name:find("MemoryBridge") and M.flashAt > lastAt
                if room and (room ~= lastRoom or flashNew or (os.clock() - lastAt > (movers and 8 or 20) and (offRoute or movers))) then
                    lastAt, lastSlab, lastRoom = os.clock(), slab, room
                    local safe
                    if room.Name:find("MemoryBridge") and next(M.flash) then
                        safe = {} for _, p in ipairs(room.Gen:GetChildren()) do local id = p:GetAttribute("MemId") if id and M.flash[id] then safe[p] = true end end
                    end
                    local txt, ok, res = "", false, nil
                    _G.__PLANBIG = on("p_big") _G.__PLANYIELD = true _G.__PLANNOPRE = true
                    for _, cap in ipairs({ 20.5, 26, 32 }) do
                        _G.__MEMSAFE = safe
                        _G.__HOPROOM, _G.__HARDGAP, _G.__SOFTGAP, _G.__TOPTOL, _G.__PLANGOAL, _G.__PLANSTART = room.Name, cap, 20.5, 0.6, nil, nil
                        ok, res = pcall(SWB["sw_plan.lua"])
                        txt = tostring(res)
                        if ok and not txt:find("NO ROUTE") then break end
                    end
                    _G.__MEMSAFE = nil _G.__PLANBIG = nil _G.__PLANYIELD = nil _G.__PLANNOPRE = nil
                    _G.__PATHST = { ok = ok, txt = txt:sub(1, 200), at = os.clock() }
                    if not ok then setText(pl, __T["Path error"])
                    elseif txt:find("NO ROUTE") then setText(pl, __T["No route from here"])
                    else
                        local n = txt:match("route: (%d+) jumps") or "?"
                        local far = tonumber(txt:match("(%d+) over")) or 0
                        setText(pl, string.format(__T["Room %d · %s jumps to exit%s"], idx, n, far > 0 and ("\n" .. far .. __T[" too far to jump (red)"]) or __T["\nAll jumps doable"]))
                    end
                end
                wasOn = true
            elseif wasOn then
                wasOn = false lastRoom = nil
                clearPath()
                setText(pl, botRunning() and __T["Paused while Auto Escape runs"] or "")
            end
        end
        while RUNNING do
            local okS, errS = pcall(step)
            if not okS then _G.__PATHERR = tostring(errS) _G.__PLANBIG = nil _G.__MEMSAFE = nil _G.__PLANYIELD = nil _G.__PLANNOPRE = nil setText(pl, __T["Path error, retrying"]) lastRoom = nil end
            task.wait(0.5)
        end
    end)
end)
section(__T["Visuals"], function()
    local Tab = Window:AddTab(__T["Visuals"], "eye")
    local CB = Tab:AddLeftGroupbox(__T["Camera"], "camera")
    CB:AddToggle("v_3p", { Text = __T["Third Person"], Default = false, Callback = function(v) if not v then camApply(false) end end })
    CB:AddSlider("v_zoom", { Text = __T["Max Zoom"], Default = 30, Min = 8, Max = 80, Rounding = 0 })
    local EB = Tab:AddRightGroupbox(__T["ESP"], "scan-eye")
    EB:AddToggle("v_mon", { Text = __T["Monster ESP"], Default = false, Tooltip = __T["State + distance"], Callback = function(v) if not v then clearEsp() end end })
    EB:AddToggle("v_code", { Text = __T["Code Signs ESP"], Default = false, Callback = function(v) if not v then clearEsp() end end })
    task.spawn(function()
        while RUNNING do
            if on("v_3p") then pcall(camApply, true) end
            local keep = {}
            local r = hrp()
            if on("v_mon") then
                local cf = M.SW:FindFirstChild("Creatures")
                if cf then for _, m in ipairs(cf:GetChildren()) do
                    local part = m:IsA("Model") and (m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)) or (m:IsA("BasePart") and m)
                    if part then
                        local stt = tostring(m:GetAttribute("State") or "?")
                        local d = r and math.floor((part.Position - r.Position).Magnitude) or 0
                        local mine = m:GetAttribute("Target") == lp.Name or m:GetAttribute("Target") == lp.UserId
                        espFor(m, stt .. " · " .. d .. "m" .. (mine and " · YOU" or ""), STATE_COL[stt] or Color3.fromRGB(200, 200, 200))
                        keep[m] = true
                    end
                end end
            end
            if on("v_code") then
                local R = M.room("LockedExit")
                if R then for _, p in ipairs(R.Gen:GetChildren()) do
                    local i = p.Name == "CodeNumber" and p:GetAttribute("CodeIndex")
                    if i then
                        local dg = "?"
                        for _, x in ipairs(p:GetDescendants()) do if x:IsA("TextLabel") and x.Text:match("^%d$") then dg = x.Text break end end
                        local taken = tostring(G.Root:GetAttribute("CodeTaken") or "")
                        local got = taken:sub(i, i) ~= "" and taken:sub(i, i) ~= "_"
                        local dist = r and math.floor((p.Position - r.Position).Magnitude) or 0
                        espFor(p, "#" .. i .. " = " .. dg .. "  · " .. dist .. "m", got and Color3.fromRGB(90, 230, 120) or Color3.fromRGB(255, 200, 60), true)
                        keep[p] = true
                    end
                end end
            end
            clearEsp(keep)
            task.wait(0.3)
        end
    end)
end)
end
section(__T["Streamer"], function()
    local Tab = Window:AddTab(__T["Streamer"], "eye")
    local ST = { HideMe = false, FakeName = "Player", HideOthers = false, HideAvatars = false, HidePlayerList = false, HideChat = false }
    ST.conns, ST.objConns, ST.orig, ST.written, ST.alias = {}, setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    ST.aliasN, ST.rev = 0, {}
    local rules, ids = {}, {}
    local function aliasFor(plr)
        if plr == lp then return (ST.FakeName ~= "" and ST.FakeName) or "Player" end
        if not ST.alias[plr] then ST.aliasN = ST.aliasN + 1 ST.alias[plr] = "Player " .. ST.aliasN end
        return ST.alias[plr]
    end
    local function active() return ST.HideMe or ST.HideOthers or ST.HideAvatars end
    local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
    local ZW = utf8.char(0x200B)
    local function unfix(t)
        if not t:find(ZW, 1, true) then return t end
        local keys = {} for k in pairs(ST.rev) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return #a > #b end)
        for _, k in ipairs(keys) do if t:find(k, 1, true) then t = t:gsub(esc(k), (ST.rev[k]:gsub("%%", "%%%%"))) end end
        return (t:gsub(ZW, ""))
    end
    local function rebuild()
        rules, ids = {}, {}
        local seen = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            local mine = plr == lp
            if (mine and ST.HideMe) or (not mine and ST.HideOthers) then
                local a = aliasFor(plr)
                for i, n in ipairs({ plr.DisplayName, plr.Name }) do
                    if type(n) == "string" and #n >= 3 and not seen[n] then
                        seen[n] = true
                        local rep = a .. ZW .. (i == 2 and ZW or "")
                        rules[#rules + 1] = { pat = "%f[%w_]" .. esc(n) .. "%f[^%w_]", plain = n, rep = rep }
                        ST.rev[rep] = n
                    end
                end
            end
            if ST.HideAvatars and (mine or ST.HideOthers) then ids[#ids + 1] = tostring(plr.UserId) end
        end
        table.sort(rules, function(a, b) return #a.plain > #b.plain end)
    end
    local function fixText(t) local o = t for _, r in ipairs(rules) do if o:find(r.plain, 1, true) then o = o:gsub(r.pat, (r.rep:gsub("%%", "%%%%"))) end end return o end
    local function fixImg(img) for _, id in ipairs(ids) do if img:find("=" .. id, 1, true) then return "" end end return img end
    local function propOf(d) if d:IsA("TextLabel") or d:IsA("TextButton") then return "Text" elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then return "Image" end end
    local function process(d)
        local p = propOf(d) if not p then return end
        local cur = d[p]
        if ST.written[d] ~= nil and cur == ST.written[d] then return end
        local fixed = p == "Text" and fixText(cur) or fixImg(cur)
        if fixed ~= cur then ST.orig[d], ST.written[d] = cur, fixed d[p] = fixed else ST.orig[d], ST.written[d] = nil, nil end
    end
    local function watch(d) if ST.objConns[d] then return end local p = propOf(d) if not p then return end ST.objConns[d] = d:GetPropertyChangedSignal(p):Connect(function() if active() then pcall(process, d) end end) pcall(process, d) end
    local function walk(inst, d) if d > 60 then return end local ok, k = pcall(inst.GetChildren, inst) if not ok then return end for _, c in ipairs(k) do pcall(watch, c) walk(c, d + 1) end end
    local function setHum(plr) local h = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then local hide = (plr == lp and ST.HideMe) or (plr ~= lp and ST.HideOthers) pcall(function() h.DisplayName = hide and aliasFor(plr) or plr.DisplayName end) end end
    local function startWatch()
        if ST.watching then return end
        ST.watching = true
        local roots = { lp:WaitForChild("PlayerGui") }
        pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
        pcall(function() local h = gethui and gethui() if typeof(h) == "Instance" then roots[#roots + 1] = h end end)
        pcall(function() roots[#roots + 1] = Workspace end)
        for i, rt in ipairs(roots) do walk(rt, 0) ST.conns["a" .. i] = rt.DescendantAdded:Connect(function(d) if propOf(d) then task.defer(function() if active() and d.Parent then watch(d) end end) end end) end
    end
    local function restoreAll()
        for d in pairs(ST.objConns) do pcall(function() if propOf(d) == "Text" then local u = unfix(d.Text) if u ~= d.Text then d.Text = u end elseif propOf(d) == "Image" and ST.orig[d] then d.Image = ST.orig[d] end end) end
        ST.written, ST.orig = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    end
    local function refresh()
        rebuild()
        for _, p in ipairs(Players:GetPlayers()) do setHum(p) end
        restoreAll()
        if active() then if ST.watching then for d in pairs(ST.objConns) do pcall(process, d) end else startWatch() end end
    end
    local function applyCore()
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, not ST.HidePlayerList) end)
        if ST.HideChat then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, false) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = false end)
        else pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, true) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = true end) end
    end
    track(Players.PlayerAdded:Connect(function() if active() then refresh() end end))
    local B = Tab:AddLeftGroupbox(__T["Hide Identity"], "user")
    B:AddToggle("st_me", { Text = __T["Hide My Name"], Default = false, Callback = function(v) ST.HideMe = v refresh() end })
    B:AddInput("st_name", { Text = __T["Fake Name"], Default = "Player", Finished = true, Callback = function(v) v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") ST.FakeName = (v ~= "" and v:sub(1, 20)) or "Player" refresh() end })
    B:AddToggle("st_others", { Text = __T["Hide Other Names"], Default = false, Callback = function(v) ST.HideOthers = v refresh() end })
    B:AddToggle("st_av", { Text = __T["Hide Avatars"], Default = false, Callback = function(v) ST.HideAvatars = v refresh() end })
    local B2 = Tab:AddRightGroupbox(__T["Hide Roblox UI"], "monitor")
    B2:AddToggle("st_list", { Text = __T["Hide Player List"], Default = false, Callback = function(v) ST.HidePlayerList = v applyCore() end })
    B2:AddToggle("st_chat", { Text = __T["Hide Chat"], Default = false, Callback = function(v) ST.HideChat = v applyCore() end })
    onClean(function() ST.HideMe, ST.HideOthers, ST.HideAvatars, ST.HidePlayerList, ST.HideChat = false, false, false, false, false pcall(refresh) pcall(applyCore) for _, c in pairs(ST.conns) do pcall(function() c:Disconnect() end) end end)
end)
